/** A disputed source flags its citers one hop. It never makes them stale. */
function deriveNeedsReview(edges: Edge[], disputed: Set<string>): Set<string> {
  const flagged = new Set<string>()
  for (const e of edges) {
    if (e.type === 'supported_by' && disputed.has(e.to)) flagged.add(e.from)
  }
  return flagged
}

